"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[43581],{50541:e=>{e.exports=JSON.parse('{"id":"2026-07-17-release-6869-meeting-features","date":"2026-07-17","products":["JaaS"],"product":"JaaS","channel":"","changeType":"Added","title":"Release 6869 meeting features","excerpt":"JaaS release 6869 adds a set of in-meeting improvements across subtitles, the whiteboard, and recording and transcription controls.","hasArticle":true,"bodyHtml":"<p>JaaS release 6869 adds a set of in-meeting improvements across subtitles, the whiteboard, and recording and transcription controls.</p>\\n<h2>Recording and transcription</h2>\\n<p>Recording and transcription can now be <strong>started and stopped independently</strong>. The buttons, dialogs, and nudges are capability-aware, so they reflect the services actually available in the meeting. Async transcription now works with a <strong>single participant</strong> \u2014 sessions start as soon as transcribing is enabled, without needing to reach a minimum participant count \u2014 and there&#39;s a new option to render speaker IDs in transcriptions.</p>\\n<h2>Subtitles</h2>\\n<ul>\\n<li>A new <code>transcription.translationEnabled</code> config flag controls live translation.</li>\\n<li>Subtitles can be toggled directly when translation is disabled, and the closed-captions button title stays in sync with its state.</li>\\n<li>Source-language subtitles are shown on stage, with the on-stage speaker name resolved correctly.</li>\\n</ul>\\n<h2>Whiteboard</h2>\\n<ul>\\n<li><strong>Image sharing</strong> is now supported on the inline web whiteboard.</li>\\n<li>The whiteboard auto-opens for remote participants when metadata propagates after a delay.</li>\\n<li>Collaboration data is validated before the whiteboard opens, with a notification shown on failure.</li>\\n<li>Non-moderators can now close the whiteboard.</li>\\n</ul>\\n<h2>Keeping the screen awake</h2>\\n<p>The screen now stays awake while a participant is <strong>waiting in the lobby</strong>, so the device doesn&#39;t sleep before they&#39;re admitted.</p>\\n<p>For the complete list of changes, language updates, and version details, see the <a href=\\"/jaas/docs/release-6869\\">release 6869 notes</a>. For more on the collaborative whiteboard, see the <a href=\\"/jaas/docs/whiteboard\\">Whiteboard guide</a>.</p>\\n"}')}}]);